def max_length(lst):
    if not lst:
        return (0, [])

    max_len = 0
    result_list = []

    for item in lst:
        length = len(item)
        if length > max_len:
            max_len = length
            result_list = [item]
        elif length == max_len:
            result_list.append(item)

    return (max_len, result_list)
